// v8: no box-fit heights any more: art is drawn at source px x KM_LAYOUT.artScale (one global factor).
// v7: point entity slots at Magnus's imported art (src/config/art_v7.js, generated by tools/import_v7.py).
// Anything not listed here keeps its ink-outlined placeholder box (see MISSING ART in README).
// status: APPROVED = explicitly approved by Magnus; CANDIDATE = in the handoff, awaiting review; STAND-IN = provisional reuse.
(function () {
  const A = window.KM_ART7; if (!A) return;
  const E = KM_ART.entities, R = p => A.root + p;
  const cutout = (key, extra) => { const c = A.cutouts[key]; return Object.assign({ img: R(c.img), anchor: c.anchor, top: c.top, status: c.status }, extra || {}); };
  const set = (id, o, box) => { E[id] = Object.assign({}, E[id] || {}, o, box ? { box: Object.assign({}, (E[id] || {}).box, box) } : {}); };
  // party: hero + 3 followers (max 4). STAND-IN: no approved bucket-knight idle/walk cutout exists yet, so the hero
  // uses the bucket-helm companion design ("stripe"); the approved drawn death shows the real hero.
  set("hero", cutout("companion_stripe", { status: "STAND-IN (v6 companion 'stripe'): hero idle/walk art missing", deathSeq: "knight_death" }));
  ["scarf", "feather", "moustache"].forEach((n, i) => set("follower_" + (i + 1), cutout("companion_" + n, { status: "CANDIDATE v6 companion design (static)" })));
  // enemies / NPCs
  set("goblin", cutout("goblin"));
  set("skeleton_knight", cutout("skeleton"));
  set("black_knight", cutout("black_knight")); // 1529 px tall source: taller than the scene at the global factor (see README v8)
  set("enchanter", cutout("warlock", { status: "STAND-IN: warlock cutout (animation-pack-v2) as Tim the Enchanter" }));
  set("hermit", cutout("scholar", { status: "STAND-IN: scholar cutout as the hermit" }));
  set("frank", cutout("friar", { status: "STAND-IN: friar cutout as Frank the priest" }));
  // killer rabbit: drawn v8 frames (ready / hit / cut / head-air / collapse / dead), per-frame holds
  set("killer_rabbit", { seq: { idle: "rabbit_idle", hurt: "rabbit_hit", death: "rabbit_death" }, status: "CANDIDATE v8 rabbit hit+death" });
  // graves with killer emblems (mid layer). grave_<killer>; others fall back to a labelled box.
  Object.entries(A.graves).forEach(([k, g]) => set("grave_" + k, { img: R(g.img), anchor: g.anchor, top: g.top, status: g.status }, { color: "#8d8a80", label: "GRAVE" }));
  // engraved numerals/operators (slices of the master reference)
  Object.assign(KM_ART.glyphs, A.glyphs);
  // strip skin: painted parchment with the ground divider (the ground IS the separator)
  KM_ART.ui.strip_bg = { img: R(A.strip_bg.img), hasDivider: true };
})();
